/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 조회조건·상태값 기본 설정.
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.parentWin = $c.data.getParameter();

    grd_Receiver.setColumnReadOnly("check", false); // 체크박스 readonly가 걸리는 문제

    // scwin.gNOTI_SVC_ID = $c.stf.getQuery("", "NOTI_SVC_ID");
