    //     scwin.read();
    //     scwin.setData();
    // } else {
    //     scwin.setHeader();
    //     scwin.setData();
    // }
}

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name rdo_target_onchange
 * @description 대상 선택
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.rdo_target_onchange = function (info) {
    try {
        scwin.changeTarget();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.rdo_target_onchange" });
    }
};

/**
 * @method
 * @name grd_Receiver_OnDblClick
 * @description grd_Receiver 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_Receiver_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "COM_ABBRV") {
            $c.stf.openPopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.grd_Receiver_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 닫기 버튼
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_close_onclick = function(e) {
    try {
        // $c.win.closePopup();
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_send_onclick
 * @description 전송 버튼 — 「전송」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_send_onclick = function(e) {
    try {
        scwin.registerMail();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_send_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 취소 버튼 — 「취소」 클릭 이벤트
