    try {
        scwin.cancel();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name btn_img_srch_onclick
 * @description 받는곳 찾기 — 「받는곳 찾기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_img_srch_onclick = async function(e) {
    try {
        // fn_SetPar = scwin.email;

        const data = {
            parScrenId: "ULDSTF07404"
        };
        const opts = {
            id: "ULDSTF07403",
            popupName: "전문평가기관 연락처 관리",
            width: 1350,
            height: 600,
            frameModal: "top",
        };
        const res = await $c.win.openPopup("ui/lst/lstinvstg/ULDSTF07403.xml", opts, data);

        dlt_receiver.setBroadcast(false);
        for(let i=0; i < res.length; i++) {
            dlt_receiver.insertRow();
            dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "chrgNm", res[i].chrgNm);
            dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "email", res[i].chrgEmail);
        }
        dlt_receiver.setBroadcast(true, true);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF07404.btn_img_srch_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description trs_Save 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        let msg = $c.data.getMessage("com_complete_0151", "전송");
        $c.win.alert(msg);
        $c.win.alert(trs_Save);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description trs_Save 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = function() {
    try {
        let msg = $c.data.getMessage("com_complete_0150", "전송");
        $c.win.alert(msg);

        if (scwin.gPvd) {
            // $c.frame.Provider("../" + scwin.gPvd).fn_Search();
            scwin.parentWin.scwin.search();
        }

        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.trs_Save_OnSuccess" });
    }
};

/**
