/**
 * @method
 * @name grd_fileList_oncelldblclick
 * @description 첨부파일 파일명 더블클릭 (다운로드)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        // TODO: 가우스에서 0: 변경사항 없는 초기상태 , R이 맞는건가?
        if (dlt_fileData.getRowStatus(dlt_fileData.getRowPosition()) === "R") {
            let url = "/api/listing/lstproc/ksqexpeval-mail/file-download";
            let data = {
                notiSvcId: dlt_fileData.getCellData(rowIndex, "notiSvcId"),
                seq: dlt_fileData.getCellData(rowIndex, "fileSeq"),
            };
            $c.data.downFile(url, dlt_fileData.getCellData(rowIndex, "fileName"), data);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.grd_fileList_oncelldblclick" });
    }
};

