/**
 * @method
 * @name btn_linedelete_onclick
 * @description 파일 삭제 — 「파일삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function (e) {
    try {
        dlt_fileData.removeRow(dlt_fileData.getRowPosition());
        scwin.uploadIdx--;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 행삽입 — 「행삽입」 클릭 이벤트
 * @param {Object} e 이벤트 객체
