 * @hidden N
 */
scwin.btn_New_onclick = function (e) {
    try {
        dlt_receiver.insertRow();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Delete_onclick
 * @description 행삭제 — 「행삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Delete_onclick = function (e) {
    try {
        let checkedRows = grd_Receiver.getCheckedIndex("check");
        dlt_receiver.setBroadcast(false);
        for (let i=checkedRows.length-1; i>=0; i--) {
            dlt_receiver.removeRow(checkedRows[i]);
        }
        dlt_receiver.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07404.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name mUpBtn_onclick
 * @description [multiUpload] 파일 선택 이벤트
 * @param {Object} e 이벤트 객체
