/**
 * @method
 * @name sbm_init_submitdone
 * @description sbm_init 통신 응답 후처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_init_submitdone = function(e) {
    dma_master.setJSON(e.responseJSON.body.mailInfo);
    dlt_fileData.setJSON(e.responseJSON.body.attchFileList);
    dlt_receiver.setJSON(e.responseJSON.body.sendReceiverList);

    ibx_title.setValue(dma_master.getJSON().title); // 메일제목
    txa_content.setValue(dma_master.getJSON().contn); // 발신내용
    rdo_target.setValue(""); // 대상 선택

    // TODO: 파일 가져와서 upload에 세팅하는게 맞나?
    // for(let i=0; i < dlt_fileData.getRowCount(); i++) {
    //     scwin.setUploadFile(i); //파일 upload 컴포넌트에 세팅
    // }
}

/**
 * @method
 * @name selectCallback
 * @description [multiUpload] 파일업로드시 파일정보 dataList에 세팅
 * @param {*} fileInfoArr fileInfoArr
 * @returns {void}
 * @hidden N
 */
scwin.selectCallback = function(fileInfoArr) {
    const fileInfos = muc.getFileInfos();

    dlt_fileData.insertRow(dlt_fileData.getRowCount());
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "fileSize",  $c.num.formatNumber(fileInfos[dlt_fileData.getRowCount()-1].size));
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "fileName",  fileInfos[dlt_fileData.getRowCount()-1].name);
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "insert",  true);
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "update",  false);
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "delete",  false);
    dlt_fileData.setCellData(dlt_fileData.getRowCount()-1, "none",  false);
}

