/**
 * @method
 * @name registerMail
 * @description 메일 보내기
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMail = async function() {
    // alert_parse(dts_Receiver.Text, ",");return;
    if (await scwin.checkForm() && scwin.checkFileSize()) {
        let msg = await $c.data.getMessage("com_crud_0198", "전송");
        let res = await $c.win.confirm(msg);
        if (res) {
            let reqMap = {
                master: dma_master.getJSON(),
                receiver: dlt_receiver.getAllJSON(),
                fileCnt: dlt_fileData.getRowCount(),
            };

            muc.changeAction("/api/listing/lstproc/ksqexpeval-mail/send"); // action 설정
            muc.setParam(0, "ksqExpEvalSendMailRequestDto", JSON.stringify(reqMap)); // request Map
            muc.startUpload();
        }
    }
};

/**
 * @method
 * @name checkFileSize
 * @description 전체 파일 사이즈 확인
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.checkFileSize = function() {
    let totalFileSize = 0;
    let isValid = true;
    for (let i = 1; i <= dlt_fileData.getRowCount(); i++) {

        totalFileSize = Number(totalFileSize) + Number(dlt_fileData.getCellData(i, "FILE_SIZE"));
    }
    if (totalFileSize > scwin.fileSizeLimit) {
        $c.win.alert($c.data.getMessage("com_empty_0235", "30MB"));
        isValid = false;
    }
    return isValid;
};

/**
 * @method
 * @name checkForm
 * @description 전송 form 확인
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.checkForm = function() {
    let msg = "";
    if ($c.str.isEmail(ibx_fromEmail.getValue()) === false) {
        $c.win.alert($c.data.getMessage("com_valid_format_0037"));

        ibx_fromEmail.focus();
        return false;
    }
    if (ibx_title.getValue() === "") {
        msg = $c.data.getMessage("com_crud_0199", "제목");
        $c.win.alert(msg);

        ibx_title.focus();
        return false;
    }
    if (ibx_title.getValue() === "") {
        msg = $c.data.getMessage("com_crud_0199", "내용");
        $c.win.alert(msg);

        txa_content.focus();
        return false;
    }
    /*
    if (getObjectValue(ibx_empNo) == "")	{
        $c.win.alert("세션정보를 받지 못했읍니다.");

        ibx_empNo.focus();
        return false;
    }
     */
    // dlt_receiver 에서 check 된 걸 찾는다.
    let total = 0;
    for (let i = 0; i <= dlt_receiver.getRowCount(); i++) {

        let chk = dlt_receiver.getCellData(i, "check");
        if (chk === "T" || chk === "1") {
            total++;
        }
    }
    if (total === 0) {
        $c.win.alert($c.data.getMessage("com_empty_0088"));
        return false;
    }
    let js_svrGubun = $c.session.js_svrGubun;
    if (js_svrGubun === 'local' || js_svrGubun === 'dev' || js_svrGubun === 'test1' || js_svrGubun === 'test2') {
        $c.win.alert($c.data.getMessage("com_notice_0005"));
    }
    return true;
};

