scwin.changeTarget = function() {

    let target = rdo_target.getValue();
    let context, title;

    if (target === "1") {
        // 주관사

        title = "(한국거래소) (" + scwin.parentWin.comNm + ") 전문평가 신청 관련";
        context = "안녕하세요. 한국거래소 기술기업상장부입니다.\n\n" + "신청하신 전문평가 관련 내용이 업데이트되었으니 제출시스템을 통해 확인하시기 바랍니다.\n" + "(전문평가기관 배정된 경우, 당해 기관에 전문평가 신청시 꼭 제출시스템을 통해 신청일을 입력해주시기\n" + "바랍니다. 필요시 미리 수정요청해주시기 바랍니다.)\n\n" + "감사합니다.";
        scwin.setTargetEmail(target);
    } else if (target === "2" || target === "3") {
        // 국책기관, TCB

        title = "(한국거래소) (" + scwin.parentWin.comNm + ") 전문평가 가능여부 회신 요청";
        if (target === "2") {

            context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + scwin.parentWin.comNm + ")의 평가대상핵심기술/사업(첨부 참조)에 대해\n" + "이해관계여부(평가이력 등을 미기재하여 신청하는 경우가 있어서 확인 요망),\n" + "일정 등을 고려하여 전문평가 가능여부를 X/XX(X)까지 회신 부탁드립니다.\n\n" + "- 평가가 불가능한 경우에도 \"불가능\"으로 메일 회신을 부탁드리며,\n" + "다수 기관이 평가의사를 밝힐 경우에는 거래소내 배정순번에 따라 평가기관이 배정됩니다.\n\n" + "오늘도 좋은 하루 되시기 바랍니다. 감사합니다!";
        } else if (target === "3") {

            context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + scwin.parentWin.comNm + ")의 평가대상핵심기술/사업(첨부 참조)에 대해\n" + "이해관계여부(평가이력 등을 미기재하여 신청하는 경우가 있어서 확인 요망),\n" + "일정 등을 고려하여 전문평가 가능여부를 X/XX(X)까지 회신 부탁드립니다.\n\n" + "- 평가가 불가능한 경우에도 \"불가능\"으로 메일 회신을 부탁드리며,\n\n" + "오늘도 좋은 하루 되시기 바랍니다. 감사합니다!";
        }

        dlt_receiver.removeAll();
    } else if (target === "4") {

        title = "(한국거래소) (" + scwin.parentWin.comNm + ") 전문평가 배정의 건";

        context = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n" + "전문평가대상기업(" + scwin.parentWin.comNm + ")의 전문평가를 귀사가 담당하게 되었음을 알려드립니다.\n" + "(" + scwin.parentWin.allocationNm + ")\n\n" + "평가인력이 최종 확정된 후 신청서를 접수하기 바라며,\n" + "신청 접수시까지 평가인력 현황표와 간단한 이력사항, 서약서를 회신해 주시기 바랍니다.\n" + "(저희 소의 감독원 검사 지적사항인 만큼 회신 일자를 지켜서 부탁드리겠습니다.)\n\n" + "기술평가는 신청일로부터 30영업일 이내에 완료될 수 있도록 부탁드리며,\n" + "혹시 평가기간 연장이 필요한 경우 평가기간 만료전에 저희와 협의를 거쳐 처리해 주시기 바랍니다.\n\n" + "기술평가 완료시에는 기술평가서와 이해관계부존재 확인서를 회신해 주시기 바랍니다.\n\n" + "감사합니다.\n";

        dlt_receiver.removeAll();
    }
    ibx_title.setValue(title);
    txa_content.setValue(context);
};

/**
 * @method
 * @name setTargetEmail
 * @description 수신자 이메일 목록을 설정한다.
 * @param {*} vTarget vTarget
 * @returns {void}
 * @hidden N
 */
scwin.setTargetEmail = function(vTarget) {

    if (vTarget === "1") {
        // 주관사
        let name = scwin.parentWin.apctNm;
        let email = scwin.parentWin.apctEmail;
        // dts_Receiver.ClearData();
        dlt_receiver.removeAll();

        dlt_receiver.insertRow();
        dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "chrgNm", name);
        dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "email", email);
    }
};

/**
 * @method
 * @name email
 * @description 함수명 : fn_Email 설명 : 전문평가 연락처
 * @param {Array} arrPar 파라미터 배열
 * @param {Boolean} isFirst 플래그
 * @returns {void}
 * @hidden N
 */
scwin.email = function(arrPar, isFirst) {
    if (isFirst) {
        // dts_Receiver.ClearData();
        dlt_receiver.removeAll();
    }

    dlt_receiver.insertRow();
    dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "chrgNm", arrPar[0]);
    dlt_receiver.setCellData(dlt_receiver.getRowCount()-1, "email", arrPar[1]);
};

/**
 * @method
 * @name formatBytes
 * @description 바이트 수를 읽기 쉬운 단위 문자열로 바꾼다.
 * @param {Number} bytes 숫자 값
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.formatBytes = function(bytes) {
    if (bytes === 0) return '0 Bytes';
    let k = 1024;
    let sizes = ['Bytes', 'KB', 'MB', 'GB'];

    let i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

