/**
 * @method
 * @name selectAll
 * @description 목록 전체 선택/해제를 토글한다.
 * @returns {void}
 * @hidden N
 */
scwin.selectAll = function() {
    // grd_Receiver.Redraw = false;
    if (scwin.gAllChk === false) {
        // 현재상태가 false이면 전체선택을 클릭릭한것

        scwin.gAllChk = true;
        dlt_receiver.setBroadcast(false);
        for (let i = 0; i < dlt_receiver.getRowCount(); i++) {
            dlt_receiver.setCellData(i, "check", "1");
        }
        dlt_receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체해제");

    } else {
        // 현재상태가  true이면 전체선택을 클릭한것
        scwin.gAllChk = false;
        dlt_receiver.setBroadcast(false);
        for (let i = 0; i < dlt_receiver.getRowCount(); i++) {
            dlt_receiver.setCellData(i, "check", "0");
        }
        dlt_receiver.setBroadcast(true, true);
        btn_SelectedAll.setValue("전체선택");
    }
};

